-- Arbeitsrecht Berufsbildung > Rechte von Arbeitgebern > Kontrolle der Arbeitsleistung (§ 14 Abs. 2 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbilder die Programmieraufgaben eines Fachinformatikers überprüfen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 2 BBiG gibt dem Arbeitgeber das Recht zur Kontrolle"}, {"text": "Nein", "correct": false, "because": "Kontrolle ist gesetzlich erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ausbilder die Arbeitsleistung eines Fachinformatikers regelmäßig bewerten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 2 BBiG erlaubt die Überwachung der Leistung"}, {"text": "Nein", "correct": false, "because": "Regelmäßige Kontrolle ist Teil des Rechts"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker die Kontrolle seiner Arbeitsleistung durch den Ausbilder akzeptieren?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 2 BBiG begründet dieses Recht des Arbeitgebers"}, {"text": "Nein", "correct": false, "because": "Kontrolle ist verpflichtend"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbilder die Arbeitsleistung eines Fachinformatikers ohne Begründung überprüfen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 2 BBiG erfordert keine spezielle Begründung"}, {"text": "Nein", "correct": false, "because": "Kontrolle ist ein allgemeines Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ausbilder die Arbeitsleistung eines Fachinformatikers auch außerhalb der Arbeitszeit kontrollieren?', 2, '[{"text": "Nein", "correct": true, "because": "Kontrolle ist auf Arbeitszeit beschränkt"}, {"text": "Ja", "correct": false, "because": "Weisungsrecht gilt nur während der Arbeitszeit"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage erlaubt einem Ausbilder, die Arbeitsleistung eines Fachinformatikers zu kontrollieren?', 2, '[{"text": "§ 14 Abs. 2 BBiG", "correct": true, "because": "Regelt das Kontrollrecht des Arbeitgebers"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Auszubildenden"}, {"text": "§ 16 BBiG", "correct": false, "because": "Regelt das Zeugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Ausbilder im Rahmen der Kontrolle der Arbeitsleistung eines Fachinformatikers tun?', 3, '[{"text": "Den geschriebenen Code überprüfen", "correct": true, "because": "Fällt unter § 14 Abs. 2 BBiG"}, {"text": "Private E-Mails des Auszubildenden lesen", "correct": false, "because": "Verstoß gegen Datenschutz"}, {"text": "Persönliche Notizen kontrollieren", "correct": false, "because": "Nicht arbeitsbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie sollte ein Fachinformatiker auf die Kontrolle seiner Arbeitsleistung reagieren?', 3, '[{"text": "Die Kontrolle akzeptieren und Feedback umsetzen", "correct": true, "because": "Fördert Zusammenarbeit und Lernen"}, {"text": "Die Kontrolle verweigern", "correct": false, "because": "Verstoß gegen § 13 BBiG"}, {"text": "Den Ausbilder ignorieren", "correct": false, "because": "Unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer hat das Recht, die Arbeitsleistung eines Fachinformatikers im Betrieb zu kontrollieren?', 2, '[{"text": "Der Ausbilder", "correct": true, "because": "§ 14 Abs. 2 BBiG legt dies fest"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule kontrolliert nicht im Betrieb"}, {"text": "Die Kollegen", "correct": false, "because": "Nur der Ausbilder ist berechtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker die Kontrolle seiner Arbeitsleistung verhindert?', 3, '[{"text": "Er kann abgemahnt oder gekündigt werden", "correct": true, "because": "Verstoß gegen Pflichten gemäß § 13 BBiG"}, {"text": "Der Ausbilder verliert sein Kontrollrecht", "correct": false, "because": "Recht bleibt bestehen"}, {"text": "Die IHK übernimmt die Kontrolle", "correct": false, "because": "IHK hat keine direkte Rolle"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Arbeitsleistung darf ein Ausbilder bei einem Fachinformatiker kontrollieren?', 4, '[{"text": "Qualität des geschriebenen Codes", "correct": true, "because": "Fällt unter § 14 Abs. 2 BBiG"}, {"text": "Einhaltung von Arbeitszeiten", "correct": true, "because": "Teil der Leistungskontrolle"}, {"text": "Private Telefonate", "correct": false, "because": "Nicht arbeitsbezogen"}, {"text": "Fortschritt bei Projekten", "correct": true, "because": "Relevanter Kontrollbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden darf ein Ausbilder zur Kontrolle der Arbeitsleistung eines Fachinformatikers nutzen?', 3, '[{"text": "Überprüfung der Arbeitsergebnisse", "correct": true, "because": "§ 14 Abs. 2 BBiG erlaubt dies"}, {"text": "Regelmäßige Berichte anfordern", "correct": true, "because": "Teil der Kontrolle"}, {"text": "Überwachung privater Aktivitäten", "correct": false, "because": "Datenschutzrechtlich unzulässig"}, {"text": "Feedbackgespräche führen", "correct": true, "because": "Fördert Leistungsbewertung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Ausbilder bei der Kontrolle der Arbeitsleistung eines Fachinformatikers nicht tun?', 3, '[{"text": "Private Daten ohne Zustimmung einsehen", "correct": true, "because": "Verstoß gegen Datenschutz"}, {"text": "Codequalität bewerten", "correct": false, "because": "Erlaubt gemäß § 14 Abs. 2 BBiG"}, {"text": "Arbeitsfortschritt überprüfen", "correct": false, "because": "Teil des Kontrollrechts"}, {"text": "Persönliche Hobbys kontrollieren", "correct": true, "because": "Nicht arbeitsbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen kann ein Ausbilder ziehen, wenn die Arbeitsleistung eines Fachinformatikers mangelhaft ist?', 4, '[{"text": "Eine Abmahnung aussprechen", "correct": true, "because": "Reaktion auf schlechte Leistung"}, {"text": "Zusätzliche Unterweisung anbieten", "correct": true, "because": "Fördert Verbesserung"}, {"text": "Die Vergütung kürzen", "correct": false, "because": "Nicht zulässig gemäß § 17 BBiG"}, {"text": "Kündigung bei wiederholtem Versagen", "correct": true, "because": "§ 22 BBiG erlaubt dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Ausbilder bei der Kontrolle der Arbeitsleistung eines Fachinformatikers?', 3, '[{"text": "Arbeitsergebnisse überprüfen", "correct": true, "because": "§ 14 Abs. 2 BBiG erlaubt dies"}, {"text": "Leistungsfeedback geben", "correct": true, "because": "Teil der Kontrolle"}, {"text": "Private Korrespondenz einsehen", "correct": false, "because": "Datenschutzrechtlich unzulässig"}, {"text": "Arbeitsweise bewerten", "correct": true, "because": "Fällt unter das Kontrollrecht"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Ausbilder darf die Arbeitsleistung eines Fachinformatikers kontrollieren. b) Die Kontrolle darf nur mit Zustimmung des Auszubildenden erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontrolle ist Recht, Zustimmung nicht erforderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Kontrolle der Arbeitsleistung umfasst die Überprüfung von Programmieraufgaben. b) Ein Ausbilder darf private Dateien eines Fachinformatikers kontrollieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Programmieraufgaben ja, private Dateien nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) § 14 Abs. 2 BBiG erlaubt die Kontrolle der Arbeitsleistung. b) Die Kontrolle darf außerhalb der Arbeitszeit stattfinden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontrolle nur während Arbeitszeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Ausbilder darf die Arbeitsleistung eines Fachinformatikers bewerten. b) Der Fachinformatiker kann die Kontrolle verweigern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bewertung ja, Verweigerung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Kontrolle der Arbeitsleistung dient der Qualitätssicherung. b) Ein Ausbilder darf die Kontrolle an Dritte delegieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualitätssicherung ja, Delegation eingeschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nur bedingt richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

